const buf = msg.payload;
function clamp(val, min, max) {
    val = Number(val);
    if (isNaN(val)) return null;
    return Math.min(Math.max(val, min), max);
}

let entity = "light.esp32h2hello_rgb_light";

// --- validate state ---
let state = (buf[0] === 1) ? 1 : 0;

if (state === 0) {
    msg.payload = {
        domain: "light",
        service: "turn_off",
        entity_id: entity,
        data: {}
    };
    return msg;
}

// ---- TURN ON ----
let data = {};

// --- validate brightness ---
let brightness = clamp(buf[1] & 0xff, 1, 255);

if (brightness !== null) {
    data.brightness = brightness;
}

// --- validate rgb ---
let rgb = [(buf[1] & 0xff00) >> 8,
            buf[2] & 0xff,
            (buf[2] & 0xff00) >> 8];

if (Array.isArray(rgb) && rgb.length === 3) {

    let r = clamp(rgb[0], 1, 255);
    let g = clamp(rgb[1], 1, 255);
    let b = clamp(rgb[2], 1, 255);


    if (r !== null && g !== null && b !== null) {

        if (!(r === 0 && g === 0 && b === 0)) {
            data.rgb_color = [r, g, b];
        }
    }
}


msg.payload = {
    domain: "light",
    entity_id: entity,
    service: "turn_on",
    data: data
};

return msg;

